// Shared presentation only; existing narratives and local databases stay separate.
const mediaPlayers=new Set();
export function registerAudio(media){mediaPlayers.add(media);const onPlay=()=>{for(const other of mediaPlayers)if(other!==media&&!other.paused)other.pause();};media.addEventListener('play',onPlay);return()=>{mediaPlayers.delete(media);media.removeEventListener('play',onPlay);};}
const PATHS={moon:'M20 14A8 8 0 0 1 10 4a8 8 0 1 0 10 10z M18 3v4 M16 5h4',heart:'M12 20S3 14 3 8c0-5 6-6 9-1 3-5 9-4 9 1 0 6-9 12-9 12z',people:'M8 3a3 3 0 1 0 0 6 3 3 0 0 0 0-6 M2 20v-4c0-6 12-6 12 0v4 M17 4a3 3 0 1 1 0 6 M17 13c3 0 5 2 5 5v2',compass:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M16 8l-3 6-5 2 3-6z M4 20L20 4',cup:'M4 10h13v5c0 7-13 7-13 0z M17 11h3c4 0 3 6-3 6 M3 21h16 M8 3c-3 2 2 3 0 5 M13 3c-3 2 2 3 0 5',note:'M6 3h10l3 3v15H6z M16 3v4h3 M9 10h7 M9 14h7 M9 18h5',family:'M8 4a3 3 0 1 0 0 6 3 3 0 0 0 0-6 M16 4a3 3 0 1 0 0 6 3 3 0 0 0 0-6 M2 20v-3c0-5 7-5 10-2 3-3 10-3 10 2v3 M9 20c-5-5 0-7 3-3 3-4 8-2 3 3z',sun:'M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10 M12 1v3 M12 20v3 M1 12h3 M20 12h3 M4 4l2 2 M18 18l2 2 M4 20l2-2 M18 6l2-2',bars:'M4 20v-5h3v5z M10 20V9h3v11z M16 20V3h3v17z'};
export function icon(name){const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');for(const [k,v] of Object.entries({viewBox:'0 0 24 24',width:24,height:24,'aria-hidden':'true',fill:'none',stroke:'currentColor','stroke-width':1.6,'stroke-linecap':'round','stroke-linejoin':'round'}))svg.setAttribute(k,v);const p=document.createElementNS(svg.namespaceURI,'path');p.setAttribute('d',PATHS[name]||PATHS.heart);svg.append(p);return svg;}
const el=(tag,text,attrs={})=>{const e=document.createElement(tag);if(text!=null)e.textContent=text;for(const [k,v] of Object.entries(attrs))e.setAttribute(k,v);return e;};
const append=(e,...children)=>{e.append(...children);return e;};
const worlds={alma:{name:'ALMA',context:'FAMILIA',description:'Un espacio para lo que compartes.',symbol:'family'},luz:{name:'LUZ',context:'VIDA PERSONAL',description:'Una posibilidad para tu día.',symbol:'sun'}};
const link=(text,view,path,attrs={})=>el('a',text,{href:'#'+view+(path?'/'+path:''),'data-view':view,...(path?{'data-path':path}:{}),...attrs});
export function simpleHomeCard(id){return cover(id,true);}
function cover(id,home){const w=worlds[id],card=el('section',null,{class:'simple-cover '+id+(home?' card door':''),'data-door':id});const art=el('div',null,{class:'simple-cover-art','aria-hidden':'true'});art.append(el('div',null,{class:'portrait'}));const body=append(el('div',null,{class:'simple-cover-body'}),el(home?'h2':'h1',w.name,home?{}:{id:'view-title',tabindex:-1}),el('p',w.context,{class:'simple-cover-kicker'}),append(el('span',null,{class:'simple-ornament'}),icon(w.symbol)),el('p',w.description,{class:'simple-cover-description'}),link('→',home?id:'recorrido',home?'portada':id,{class:'simple-enter','aria-label':home?'Entrar en '+w.name:'Continuar con '+w.name}));append(card,art,body);return card;}
export function renderSimpleWorld(main,id){main.dataset.simpleWorld=id;const nav=append(el('nav',null,{class:'simple-top','aria-label':'Navegación de '+worlds[id].name}),link('← Volver','inicio',null),append(link('Aquí contigo','apoyo',null),icon('people')),link('Inicio','inicio',null));append(main,nav,cover(id,false));}
